@Test
public void testAlertEvent() {
    StatsDClient client = mock(StatsDClient.class);
    StatsDEmitter emitter = new StatsDEmitter(new StatsDEmitterConfig("localhost", 8888, null, null, true, null, null, true, null, true, true, null, null, null, null), new ObjectMapper(), client);
    Event expectedEvent = Event.builder().withPriority(Event.Priority.NORMAL).withAlertType(Event.AlertType.WARNING).withTitle("something bad happened [exception]").withText("{\"exception\":\"NPE\"}").build();
    emitter.emit(AlertBuilder.create("something bad happened [%s]", "exception").severity(AlertEvent.Severity.ANOMALY).addData(ImmutableMap.of("exception", "NPE")).build("druid/broker", "brokerHost1"));
    final ArgumentCaptor<Event> eventArgumentCaptor = ArgumentCaptor.forClass(Event.class);
    verify(client).recordEvent(eventArgumentCaptor.capture(), eq("feed:alerts"), eq("druid_service:druid/broker"), eq("severity:anomaly"), eq("hostname:brokerHost1"));
    Event actualEvent = eventArgumentCaptor.getValue();
    Assert.assertTrue(actualEvent.getMillisSinceEpoch() > 0);
    Assert.assertEquals(expectedEvent.getPriority(), actualEvent.getPriority());
    Assert.assertEquals(expectedEvent.getAlertType(), actualEvent.getAlertType());
    Assert.assertEquals(expectedEvent.getTitle(), actualEvent.getTitle());
    Assert.assertEquals(expectedEvent.getText(), actualEvent.getText());
}

