@Test
public void testStartCompaction() {
    final List<DataSegment> wikiSegments = CreateDataSegments.ofDatasource(TestDataSource.WIKI).eachOfSizeInMb(100);
    wikiSegments.forEach(segmentsMetadataManager::addSegment);
    scheduler.becomeLeader();
    scheduler.startCompaction(TestDataSource.WIKI, InlineSchemaDataSourceCompactionConfig.builder().forDataSource(TestDataSource.WIKI).withSkipOffsetFromLatest(Period.seconds(0)).build());
    executor.finishNextPendingTask();
    ArgumentCaptor<Task> taskArgumentCaptor = ArgumentCaptor.forClass(Task.class);
    Mockito.verify(taskQueue, Mockito.times(1)).add(taskArgumentCaptor.capture());
    Task submittedTask = taskArgumentCaptor.getValue();
    Assert.assertNotNull(submittedTask);
    Assert.assertTrue(submittedTask instanceof CompactionTask);
    final CompactionTask compactionTask = (CompactionTask) submittedTask;
    Assert.assertEquals(TestDataSource.WIKI, compactionTask.getDataSource());
    final AutoCompactionSnapshot.Builder expectedSnapshot = AutoCompactionSnapshot.builder(TestDataSource.WIKI);
    expectedSnapshot.incrementCompactedStats(CompactionStatistics.create(100_000_000, 1, 1));
    Assert.assertEquals(expectedSnapshot.build(), scheduler.getCompactionSnapshot(TestDataSource.WIKI));
    Assert.assertEquals(Collections.singletonMap(TestDataSource.WIKI, expectedSnapshot.build()), scheduler.getAllCompactionSnapshots());
    serviceEmitter.verifyValue(Stats.Compaction.SUBMITTED_TASKS.getMetricName(), 1L);
    serviceEmitter.verifyValue(Stats.Compaction.COMPACTED_BYTES.getMetricName(), 100_000_000L);
    scheduler.stopBeingLeader();
}

@Test
public void testStopCompaction() {
    final List<DataSegment> wikiSegments = CreateDataSegments.ofDatasource(TestDataSource.WIKI).eachOfSizeInMb(100);
    wikiSegments.forEach(segmentsMetadataManager::addSegment);
    scheduler.becomeLeader();
    scheduler.startCompaction(TestDataSource.WIKI, InlineSchemaDataSourceCompactionConfig.builder().forDataSource(TestDataSource.WIKI).withSkipOffsetFromLatest(Period.seconds(0)).build());
    scheduler.stopCompaction(TestDataSource.WIKI);
    executor.finishNextPendingTask();
    Mockito.verify(taskQueue, Mockito.never()).add(ArgumentMatchers.any());
    Assert.assertEquals(AutoCompactionSnapshot.builder(TestDataSource.WIKI).withStatus(AutoCompactionSnapshot.ScheduleStatus.NOT_ENABLED).build(), scheduler.getCompactionSnapshot(TestDataSource.WIKI));
    Assert.assertTrue(scheduler.getAllCompactionSnapshots().isEmpty());
    serviceEmitter.verifyNotEmitted(Stats.Compaction.SUBMITTED_TASKS.getMetricName());
    serviceEmitter.verifyNotEmitted(Stats.Compaction.COMPACTED_BYTES.getMetricName());
    scheduler.stopBeingLeader();
}

@Test
public void testStartAndStop() {
    OverlordDuty testDuty1 = Mockito.mock(OverlordDuty.class);
    Mockito.when(testDuty1.isEnabled()).thenReturn(true);
    Mockito.when(testDuty1.getSchedule()).thenReturn(new DutySchedule(1, 0));
    OverlordDuty testDuty2 = Mockito.mock(OverlordDuty.class);
    Mockito.when(testDuty2.isEnabled()).thenReturn(true);
    Mockito.when(testDuty2.getSchedule()).thenReturn(new DutySchedule(1, 0));
    ScheduledExecutorFactory executorFactory = Mockito.mock(ScheduledExecutorFactory.class);
    ScheduledExecutorService executorService = Mockito.mock(ScheduledExecutorService.class);
    Mockito.when(executorFactory.create(ArgumentMatchers.eq(1), ArgumentMatchers.anyString())).thenReturn(executorService);
    OverlordDutyExecutor dutyExecutor = new OverlordDutyExecutor(executorFactory, ImmutableSet.of(testDuty1, testDuty2));
    // Invoke start multiple times
    dutyExecutor.start();
    dutyExecutor.start();
    dutyExecutor.start();
    // Verify that executor is initialized and each duty is scheduled
    Mockito.verify(executorFactory, Mockito.times(1)).create(ArgumentMatchers.eq(1), ArgumentMatchers.anyString());
    Mockito.verify(executorService, Mockito.times(2)).schedule(ArgumentMatchers.any(Runnable.class), ArgumentMatchers.anyLong(), ArgumentMatchers.any());
    // Invoke stop multiple times
    dutyExecutor.stop();
    dutyExecutor.stop();
    dutyExecutor.stop();
    // Verify that the executor shutdown is invoked just once
    Mockito.verify(executorService, Mockito.times(1)).shutdownNow();
}

