@Test
public void testSchedulerWithSuccessfulTaskSubmission() {
    final SqlTaskStatus expectedTaskStatus = new SqlTaskStatus(TASK_ID_FOO1, TaskState.SUCCESS, null);
    Mockito.when(brokerClient.submitSqlTask(query1)).thenReturn(Futures.immediateFuture(expectedTaskStatus));
    scheduler.start();
    scheduler.startScheduledIngestion(SUPERVISOR_ID_FOO, DATASOURCE, IMMEDIATE_SCHEDULER_CONFIG, query1);
    verifySchedulerState(SUPERVISOR_ID_FOO, ScheduledBatchSupervisor.State.RUNNING);
    executor.finishNextPendingTasks(1);
    verifySchedulerStateWithTasks(SUPERVISOR_ID_FOO, ScheduledBatchSupervisor.State.RUNNING, ImmutableList.of(TaskStatus.success(expectedTaskStatus.getTaskId())));
    scheduler.stopScheduledIngestion(SUPERVISOR_ID_FOO);
    verifySchedulerStateWithTasks(SUPERVISOR_ID_FOO, ScheduledBatchSupervisor.State.SUSPENDED, ImmutableList.of(TaskStatus.success(expectedTaskStatus.getTaskId())));
    scheduler.stop();
    assertNull(scheduler.getSupervisorStatus(SUPERVISOR_ID_FOO));
    serviceEmitter.verifyEmitted("task/scheduledBatch/submit/success", ImmutableMap.of(DruidMetrics.ID, SUPERVISOR_ID_FOO), 1);
}

