public void testParseMalformedDataWithAllowedParseExceptions_thenNoException() throws IOException {
    final InputRowParser<ByteBuffer> parser = new StringInputRowParser(new JSONParseSpec(TIMESTAMP_SPEC, DimensionsSpec.EMPTY, JSONPathSpec.DEFAULT, Collections.emptyMap(), false), StringUtils.UTF8_STRING);
    final int maxAllowedParseExceptions = 1;
    final StreamChunkParser<ByteEntity> chunkParser = new StreamChunkParser<>(parser, mockedByteEntityReader, row -> true, rowIngestionMeters, new ParseExceptionHandler(rowIngestionMeters, false, maxAllowedParseExceptions, 0));
