            final DruidServer server = new DruidServer(serverMetadata.getName(), serverMetadata.getHostAndPort(), serverMetadata.getHostAndTlsPort(), serverMetadata.getMaxSize(), serverMetadata.getType(), serverMetadata.getTier(), serverMetadata.getPriority());
            serverSelector.addServerAndUpdateSegment(new QueryableDruidServer(server, null), dataSegment);
        }
        timeline.add(dataSegment.getInterval(), dataSegment.getVersion(), dataSegment.getShardSpec().createChunk(serverSelector));
    }
    Mockito.when(serverView.getDruidServerMetadatas()).thenReturn(SERVERS);
