    final DartQueryInfo remoteQueryInfo = new DartQueryInfo("sid", "did2", "SELECT 2", "localhost:1002", AUTHENTICATOR_NAME, DIFFERENT_REGULAR_USER_NAME, DateTimes.of("2001"), ControllerHolder.State.RUNNING.toString());
    Mockito.when(dartSqlClient.getRunningQueries(true)).thenReturn(Futures.immediateFuture(new GetQueriesResponse(Collections.singletonList(remoteQueryInfo))));
