 * Test where a superuser calls {@link SqlResource#doGetRunningQueries} with selfOnly disabled, and where the
 * remote server has a problem.
 */
@Test
public void test_getRunningQueries_global_remoteError_superUser() {
    Mockito.when(httpServletRequest.getAttribute(AuthConfig.DRUID_AUTHENTICATION_RESULT)).thenReturn(makeAuthenticationResult(CalciteTests.TEST_SUPERUSER_NAME));
    // REGULAR_USER_NAME runs a query locally.
    final ControllerHolder localHolder = setUpMockRunningQuery(REGULAR_USER_NAME);
    // Remote call fails.
    Mockito.when(dartSqlClient.getRunningQueries(true)).thenReturn(Futures.immediateFailedFuture(new IOException("something went wrong")));
    // We only see local queries, because the remote call failed. (The entire call doesn't fail; we see what we
    // were able to fetch.)
    Assertions.assertEquals(new GetQueriesResponse(ImmutableList.of(DartQueryInfo.fromControllerHolder(localHolder))), sqlResource.doGetRunningQueries(null, httpServletRequest).getEntity());
    controllerRegistry.deregister(localHolder);
}

/**
 * Test where {@link #REGULAR_USER_NAME} and {@link #DIFFERENT_REGULAR_USER_NAME} issue queries, and
 * {@link #REGULAR_USER_NAME} calls {@link SqlResource#doGetRunningQueries} with selfOnly disabled.
 */
@Test
public void test_getRunningQueries_global_regularUser() {
    Mockito.when(httpServletRequest.getAttribute(AuthConfig.DRUID_AUTHENTICATION_RESULT)).thenReturn(makeAuthenticationResult(REGULAR_USER_NAME));
    // REGULAR_USER_NAME runs a query locally.
    final ControllerHolder localHolder = setUpMockRunningQuery(REGULAR_USER_NAME);
    // DIFFERENT_REGULAR_USER_NAME runs a query remotely.
    final DartQueryInfo remoteQueryInfo = new DartQueryInfo("sid", "did2", "SELECT 2", "localhost:1002", AUTHENTICATOR_NAME, DIFFERENT_REGULAR_USER_NAME, DateTimes.of("2000"), ControllerHolder.State.RUNNING.toString());
    Mockito.when(dartSqlClient.getRunningQueries(true)).thenReturn(Futures.immediateFuture(new GetQueriesResponse(Collections.singletonList(remoteQueryInfo))));
    // The endpoint returns only the query issued by REGULAR_USER_NAME.
    Assertions.assertEquals(new GetQueriesResponse(ImmutableList.of(DartQueryInfo.fromControllerHolder(localHolder).withoutAuthenticationResult())), sqlResource.doGetRunningQueries(null, httpServletRequest).getEntity());
    controllerRegistry.deregister(localHolder);
}

