}

// This test is a Frankenstein creation: it uses the injector set up by the
// SqlTestFramework to pull items from that are then used to create another
// injector that has the MSQ dependencies. This allows the test to create a
// "shadow" statement factory that is used for tests. It works... kinda.
//
// Better would be to sort through the Guice stuff and move it into the
// configureGuice() method above: use the SQL test framework injector so
// that everything is coordinated. Use the planner factory provided by that
// framework.
//
// Leaving well enough alone for now because any change should be done by
// someone familiar with the rather complex setup code below.
//
// One brute-force attempt ran afoul of circular dependencies: the SQL engine
// is created in the main injector, but it depends on the SegmentCacheManagerFactory
// which depends on the object mapper that the injector will provide, once it
// is built, but has not yet been build while we build the SQL engine.
@BeforeEach
public void setUp2() throws Exception {
    groupByBuffers = TestGroupByBuffers.createDefault();
    SqlTestFramework qf = queryFramework();
    objectMapper = setupObjectMapper(qf.injector());
    indexIO = new IndexIO(objectMapper, ColumnConfig.DEFAULT);
    segmentCacheManager = new SegmentCacheManagerFactory(indexIO, objectMapper).manufacturate(newTempFolder("cacheManager"));
    segmentManager = new MSQTestSegmentManager(segmentCacheManager);
    List<Module> modules = ImmutableList.of(binder -> {
        DruidProcessingConfig druidProcessingConfig = new DruidProcessingConfig() {

            @Override
            public int getNumThreads() {
                return 1;
            }

            @Override
            public int intermediateComputeSizeBytes() {
                return 10_000_000;
            }

            @Override
            public String getFormatString() {
                return "test";
            }
        };
        GroupByQueryConfig groupByQueryConfig = new GroupByQueryConfig();
        GroupingEngine groupingEngine = GroupByQueryRunnerTest.makeQueryRunnerFactory(groupByQueryConfig, groupByBuffers).getGroupingEngine();
        binder.bind(GroupingEngine.class).toInstance(groupingEngine);
        binder.bind(DruidProcessingConfig.class).toInstance(druidProcessingConfig);
        binder.bind(new TypeLiteral<Set<NodeRole>>() {
        }).annotatedWith(Self.class).toInstance(ImmutableSet.of(NodeRole.PEON));
        binder.bind(QueryProcessingPool.class).toInstance(new ForwardingQueryProcessingPool(Execs.singleThreaded("Test-runner-processing-pool")));
        binder.bind(SegmentWriteOutMediumFactory.class).toInstance(TmpFileSegmentWriteOutMediumFactory.instance());
        binder.bind(DataSegmentProvider.class).toInstance((segmentId, channelCounters, isReindex) -> getSupplierForSegment(this::newTempFolder, segmentId));
        binder.bind(DataServerQueryHandlerFactory.class).toInstance(getTestDataServerQueryHandlerFactory());
        binder.bind(IndexIO.class).toInstance(indexIO);
        binder.bind(SpecificSegmentsQuerySegmentWalker.class).toInstance(qf.walker());
        LocalDataSegmentPusherConfig config = new LocalDataSegmentPusherConfig();
        config.storageDirectory = newTempFolder("storageDir");
        binder.bind(DataSegmentPusher.class).toInstance(new MSQTestDelegateDataSegmentPusher(new LocalDataSegmentPusher(config), segmentManager));
        binder.bind(DataSegmentAnnouncer.class).toInstance(new NoopDataSegmentAnnouncer());
        binder.bindConstant().annotatedWith(PruneLoadSpec.class).to(false);
        // Client is not used in tests
        binder.bind(Key.get(ServiceClientFactory.class, EscalatedGlobal.class)).toProvider(Providers.of(null));
        // fault tolerance module
        try {
            JsonConfigProvider.bind(binder, MSQDurableStorageModule.MSQ_INTERMEDIATE_STORAGE_PREFIX, StorageConnectorProvider.class, MultiStageQuery.class);
            localFileStorageDir = newTempFolder("faultStorageDir");
            localFileStorageConnector = Mockito.spy(new LocalFileStorageConnector(localFileStorageDir));
            binder.bind(Key.get(StorageConnector.class, MultiStageQuery.class)).toProvider(() -> localFileStorageConnector);
        } catch (IOException e) {
            throw new ISE(e, "Unable to create setup storage connector");
        }
        binder.bind(DataSegment.PruneSpecsHolder.class).toInstance(DataSegment.PruneSpecsHolder.DEFAULT);
    }, // Requirement of WorkerMemoryParameters.createProductionInstanceForWorker(injector)
    binder -> binder.bind(AppenderatorsManager.class).toProvider(() -> null), // Requirement of JoinableFactoryModule
    binder -> binder.bind(SegmentManager.class).toInstance(EasyMock.createMock(SegmentManager.class)), new JoinableFactoryModule(), new IndexingServiceTuningConfigModule(), Modules.override(new MSQSqlModule()).with(binder -> {
        // Our Guice configuration currently requires bindings to exist even if they aren't ever used, the
        // following bindings are overriding other bindings that end up needing a lot more dependencies.
        // We replace the bindings with something that returns null to make things more brittle in case they
        // actually are used somewhere in the test.
        binder.bind(SqlStatementFactory.class).annotatedWith(MultiStageQuery.class).toProvider(Providers.of(null));
        binder.bind(SqlToolbox.class).toProvider(Providers.of(null));
        binder.bind(MSQTaskSqlEngine.class).toProvider(Providers.of(null));
    }), new ExpressionModule(), new MSQExternalDataSourceModule(), new LookylooModule(), new SegmentWranglerModule(), new HllSketchModule(), binder -> binder.bind(Bouncer.class).toInstance(new Bouncer(1)), binder -> binder.bind(PolicyEnforcer.class).toInstance(NoopPolicyEnforcer.instance()));
    // adding node role injection to the modules, since CliPeon would also do that through run method
    injector = new CoreInjectorBuilder(new StartupInjectorBuilder().build(), ImmutableSet.of(NodeRole.PEON)).addAll(modules).build();
    testTaskActionClient = Mockito.spy(new MSQTestTaskActionClient(objectMapper, injector));
    indexingServiceClient = new MSQTestOverlordServiceClient(objectMapper, injector, testTaskActionClient, workerMemoryParameters, loadedSegmentsMetadata);
    CatalogResolver catalogResolver = createMockCatalogResolver();
    final InProcessViewManager viewManager = new InProcessViewManager(SqlTestFramework.DRUID_VIEW_MACRO_FACTORY);
    DruidSchemaCatalog rootSchema = QueryFrameworkUtils.createMockRootSchema(CalciteTests.INJECTOR, qf.conglomerate(), qf.walker(), new PlannerConfig(), viewManager, new NoopDruidSchemaManager(), CalciteTests.TEST_AUTHORIZER_MAPPER, CatalogResolver.NULL_RESOLVER);
    final SqlEngine engine = new MSQTaskSqlEngine(indexingServiceClient, qf.queryJsonMapper().copy().registerModules(new MSQSqlModule().getJacksonModules()), new SegmentGenerationTerminalStageSpecFactory(), injector.getInstance(MSQTaskQueryKitSpecFactory.class), null);
    authorizerMapper = new AuthorizerMapper(null) {

        @Override
        public Authorizer getAuthorizer(String name) {
            // default allow read/write access to external resources
            return (authenticationResult, resource, action) -> new TestAuthorizer(authenticationResult, resource, action).defaultPolicyOnReadTable(CalciteTests.POLICY_RESTRICTION).allowIfSuperuser(CalciteTests.TEST_SUPERUSER_NAME).denyIfResourceNameHasKeyword("forbidden").allowIfResourceTypeIs(Set.of(ResourceType.DATASOURCE, ResourceType.VIEW, ResourceType.QUERY_CONTEXT, ResourceType.EXTERNAL)).access().orElse(Access.DENIED);
        }
    };
    PlannerFactory plannerFactory = new PlannerFactory(rootSchema, qf.operatorTable(), qf.macroTable(), PLANNER_CONFIG_DEFAULT, authorizerMapper, objectMapper, CalciteTests.DRUID_SCHEMA_NAME, new CalciteRulesManager(ImmutableSet.of()), CalciteTests.createJoinableFactoryWrapper(), catalogResolver, new AuthConfig(), NoopPolicyEnforcer.instance(), new DruidHookDispatcher());
    sqlStatementFactory = QueryFrameworkUtils.createSqlMultiStatementFactory(engine, plannerFactory);
    EmittingLogger.registerEmitter(new NoopServiceEmitter());
}

