public void setup() {
    byte[] randomBytes = new byte[1024];
    ThreadLocalRandom.current().nextBytes(randomBytes);
    buf = ByteBuffer.wrap(randomBytes);
    timeSelector = new BaseLongVectorValueSelector(new NoFilterVectorOffset(times.length, 0, times.length)) {

        @Override
        public long[] getLongVector() {
            return times;
        }

        @Nullable
        @Override
        public boolean[] getNullVector() {
            return null;
        }
    };
    selector = new VectorObjectSelector() {

        @Override
        public Object[] getObjectVector() {
            return VALUES;
        }

        @Override
        public int getMaxVectorSize() {
            return 4;
        }

        @Override
        public int getCurrentVectorSize() {
            return 0;
        }
    };
    timeSelectorForPairs = new BaseLongVectorValueSelector(new NoFilterVectorOffset(timesSame.length, 0, timesSame.length)) {

        @Override
        public long[] getLongVector() {
            return timesSame;
        }

        @Nullable
        @Override
        public boolean[] getNullVector() {
            return null;
        }
    };
    selectorForPairs = new VectorObjectSelector() {

        @Override
        public Object[] getObjectVector() {
            return pairs;
        }

        @Override
        public int getMaxVectorSize() {
            return 2;
        }

        @Override
        public int getCurrentVectorSize() {
            return 0;
        }
    };
    nonStringValueSelector = new BaseLongVectorValueSelector(new NoFilterVectorOffset(LONG_VALUES.length, 0, LONG_VALUES.length)) {

        @Override
        public long[] getLongVector() {
            return LONG_VALUES;
        }

        @Override
        public float[] getFloatVector() {
            return FLOAT_VALUES;
        }

        @Override
        public double[] getDoubleVector() {
            return DOUBLE_VALUES;
        }

        @Nullable
        @Override
        public boolean[] getNullVector() {
            return NULLS;
        }

        @Override
        public int getMaxVectorSize() {
            return 4;
        }

        @Override
        public int getCurrentVectorSize() {
            return 4;
        }
    };
    selectorFactory = new VectorColumnSelectorFactory() {

        @Override
        public ReadableVectorInspector getReadableVectorInspector() {
            return new NoFilterVectorOffset(VALUES.length, 0, VALUES.length);
        }

        @Override
        public SingleValueDimensionVectorSelector makeSingleValueDimensionSelector(DimensionSpec dimensionSpec) {
            return null;
        }

        @Override
        public MultiValueDimensionVectorSelector makeMultiValueDimensionSelector(DimensionSpec dimensionSpec) {
            return null;
        }

        @Override
        public VectorValueSelector makeValueSelector(String column) {
            if (TIME_COL.equals(column)) {
                return timeSelector;
            } else if (FIELD_NAME_LONG.equals(column)) {
                return nonStringValueSelector;
            }
            return null;
        }

        @Override
        public VectorObjectSelector makeObjectSelector(String column) {
            if (FIELD_NAME.equals(column)) {
                return selector;
            } else {
                return null;
            }
        }

        @Nullable
        @Override
        public ColumnCapabilities getColumnCapabilities(String column) {
            if (FIELD_NAME.equals(column)) {
                return ColumnCapabilitiesImpl.createSimpleSingleValueStringColumnCapabilities();
            } else if (FIELD_NAME_LONG.equals(column)) {
                return ColumnCapabilitiesImpl.createSimpleNumericColumnCapabilities(ColumnType.LONG);
            }
            return null;
        }
    };
