@Test
public void testColdDatasourceSchema_verifyStaleDatasourceRemoved() {
    DataSegment coldSegmentAlpha = DataSegment.builder().dataSource("alpha").interval(Intervals.of("2000/P2Y")).version("1").shardSpec(new LinearShardSpec(0)).size(0).build();
    DataSegment coldSegmentBeta = DataSegment.builder().dataSource("beta").interval(Intervals.of("2000/P2Y")).version("1").shardSpec(new LinearShardSpec(0)).size(0).build();
    DataSegment coldSegmentGamma = DataSegment.builder().dataSource("gamma").interval(Intervals.of("2000/P1Y")).version("1").shardSpec(new LinearShardSpec(0)).size(0).build();
    DataSegment hotSegmentGamma = DataSegment.builder().dataSource("gamma").interval(Intervals.of("2001/P2Y")).version("1").shardSpec(new LinearShardSpec(0)).size(0).build();
    ImmutableMap.Builder<SegmentId, SegmentMetadata> segmentStatsMap = new ImmutableMap.Builder<>();
    segmentStatsMap.put(coldSegmentAlpha.getId(), new SegmentMetadata(20L, "cold"));
    segmentStatsMap.put(coldSegmentBeta.getId(), new SegmentMetadata(20L, "cold"));
    segmentStatsMap.put(hotSegmentGamma.getId(), new SegmentMetadata(20L, "hot"));
    segmentStatsMap.put(coldSegmentGamma.getId(), new SegmentMetadata(20L, "cold"));
    ImmutableMap.Builder<String, SchemaPayload> schemaPayloadMap = new ImmutableMap.Builder<>();
    schemaPayloadMap.put("cold", new SchemaPayload(RowSignature.builder().add("dim1", ColumnType.STRING).add("c1", ColumnType.STRING).add("c2", ColumnType.LONG).build()));
    schemaPayloadMap.put("hot", new SchemaPayload(RowSignature.builder().add("c3", ColumnType.STRING).add("c4", ColumnType.STRING).build()));
    segmentSchemaCache.resetSchemaForPublishedSegments(segmentStatsMap.build(), schemaPayloadMap.build());
    Mockito.when(segmentsMetadataManager.getRecentDataSourcesSnapshot()).thenReturn(DataSourcesSnapshot.fromUsedSegments(List.of(coldSegmentAlpha, hotSegmentGamma, coldSegmentGamma)));
    CoordinatorSegmentMetadataCache schema = new CoordinatorSegmentMetadataCache(getQueryLifecycleFactory(walker), serverView, SEGMENT_CACHE_CONFIG_DEFAULT, new NoopEscalator(), new InternalQueryConfig(), new NoopServiceEmitter(), segmentSchemaCache, backFillQueue, segmentsMetadataManager, segmentsMetadataManagerConfigSupplier);
    SegmentReplicaCount zeroSegmentReplicaCount = Mockito.mock(SegmentReplicaCount.class);
    SegmentReplicaCount nonZeroSegmentReplicaCount = Mockito.mock(SegmentReplicaCount.class);
    Mockito.when(zeroSegmentReplicaCount.required()).thenReturn(0);
    Mockito.when(nonZeroSegmentReplicaCount.required()).thenReturn(1);
    SegmentReplicationStatus segmentReplicationStatus = Mockito.mock(SegmentReplicationStatus.class);
    Mockito.when(segmentReplicationStatus.getReplicaCountsInCluster(ArgumentMatchers.eq(coldSegmentAlpha.getId()))).thenReturn(zeroSegmentReplicaCount);
    Mockito.when(segmentReplicationStatus.getReplicaCountsInCluster(ArgumentMatchers.eq(coldSegmentBeta.getId()))).thenReturn(zeroSegmentReplicaCount);
    Mockito.when(segmentReplicationStatus.getReplicaCountsInCluster(ArgumentMatchers.eq(coldSegmentGamma.getId()))).thenReturn(zeroSegmentReplicaCount);
    Mockito.when(segmentReplicationStatus.getReplicaCountsInCluster(ArgumentMatchers.eq(hotSegmentGamma.getId()))).thenReturn(nonZeroSegmentReplicaCount);
    schema.updateSegmentReplicationStatus(segmentReplicationStatus);
    schema.refreshColdSegmentSchemas();
    // alpha has only 1 cold segment
    Assert.assertNotNull(schema.getDatasource("alpha"));
    // gamma has both hot and cold segment
    Assert.assertNotNull(schema.getDatasource("gamma"));
    // assert that cold schema for gamma doesn't contain any columns from hot segment
    RowSignature rowSignature = schema.getDatasource("gamma").getRowSignature();
    Assert.assertTrue(rowSignature.contains("dim1"));
    Assert.assertTrue(rowSignature.contains("c1"));
    Assert.assertTrue(rowSignature.contains("c2"));
