@Test
public void testDumpRows() throws Exception {
    Injector injector = Mockito.mock(Injector.class);
    ObjectMapper mapper = TestHelper.makeJsonMapper();
    mapper.registerModules(BuiltInTypesModule.getJacksonModulesList());
    mapper.setInjectableValues(new InjectableValues.Std().addValue(ExprMacroTable.class.getName(), TestExprMacroTable.INSTANCE).addValue(ObjectMapper.class.getName(), mapper).addValue(DefaultColumnFormatConfig.class, new DefaultColumnFormatConfig(null, null, null)));
    Mockito.when(injector.getInstance(Key.get(ObjectMapper.class, Json.class))).thenReturn(mapper);
    Mockito.when(injector.getInstance(DefaultColumnFormatConfig.class)).thenReturn(new DefaultColumnFormatConfig(null, null, null));
    List<Segment> segments = createSegments(tempFolder, closer);
    QueryableIndex queryableIndex = segments.get(0).as(QueryableIndex.class);
    File outputFile = tempFolder.newFile();
    DumpSegment.runDump(injector, outputFile.getPath(), queryableIndex, DumpSegment.getColumnsToInclude(queryableIndex, Collections.emptyList()), null, false);
