@Test
public void testCalciteLiteralToDruidLiteral() {
    final RexBuilder rexBuilder = new RexBuilder(DruidTypeSystem.TYPE_FACTORY);
    final PlannerContext plannerContext = Mockito.mock(PlannerContext.class);
    Mockito.when(plannerContext.getTimeZone()).thenReturn(DateTimeZone.UTC);
    assertDruidLiteral(new DruidLiteral(ExpressionType.STRING, null), Expressions.calciteLiteralToDruidLiteral(plannerContext, rexBuilder.makeNullLiteral(rexBuilder.getTypeFactory().createSqlType(SqlTypeName.VARCHAR))));
    assertDruidLiteral(new DruidLiteral(ExpressionType.STRING, ""), Expressions.calciteLiteralToDruidLiteral(plannerContext, rexBuilder.makeLiteral("")));
    assertDruidLiteral(new DruidLiteral(ExpressionType.LONG, null), Expressions.calciteLiteralToDruidLiteral(plannerContext, rexBuilder.makeNullLiteral(rexBuilder.getTypeFactory().createSqlType(SqlTypeName.BIGINT))));
    assertDruidLiteral(new DruidLiteral(ExpressionType.STRING, null), Expressions.calciteLiteralToDruidLiteral(plannerContext, rexBuilder.makeNullLiteral(rexBuilder.getTypeFactory().createSqlType(SqlTypeName.NULL))));
    assertDruidLiteral(new DruidLiteral(ExpressionType.STRING, "abc"), Expressions.calciteLiteralToDruidLiteral(plannerContext, rexBuilder.makeLiteral("abc")));
    assertDruidLiteral(new DruidLiteral(ExpressionType.LONG, 1L), Expressions.calciteLiteralToDruidLiteral(plannerContext, rexBuilder.makeLiteral(true)));
    assertDruidLiteral(new DruidLiteral(ExpressionType.LONG, 123L), Expressions.calciteLiteralToDruidLiteral(plannerContext, rexBuilder.makeExactLiteral(BigDecimal.valueOf(123L), rexBuilder.getTypeFactory().createSqlType(SqlTypeName.INTEGER))));
    assertDruidLiteral(new DruidLiteral(ExpressionType.DOUBLE, 123.0), Expressions.calciteLiteralToDruidLiteral(plannerContext, rexBuilder.makeExactLiteral(BigDecimal.valueOf(123L), rexBuilder.getTypeFactory().createSqlType(SqlTypeName.DECIMAL))));
    assertDruidLiteral(new DruidLiteral(ExpressionType.LONG, DateTimes.of("2000").getMillis()), Expressions.calciteLiteralToDruidLiteral(plannerContext, Calcites.jodaToCalciteTimestampLiteral(rexBuilder, DateTimes.of("2000"), DateTimeZone.UTC, DruidTypeSystem.DEFAULT_TIMESTAMP_PRECISION)));
    assertDruidLiteral(new DruidLiteral(ExpressionType.LONG, DateTimes.of("2000").getMillis()), Expressions.calciteLiteralToDruidLiteral(plannerContext, rexBuilder.makeDateLiteral(Calcites.jodaToCalciteDateString(DateTimes.of("2000"), DateTimeZone.UTC))));
    assertDruidLiteral(new DruidLiteral(ExpressionType.LONG, 3L), Expressions.calciteLiteralToDruidLiteral(plannerContext, rexBuilder.makeIntervalLiteral(BigDecimal.valueOf(3), new SqlIntervalQualifier(TimeUnit.DAY, TimeUnit.HOUR, SqlParserPos.ZERO))));
    assertDruidLiteral(new DruidLiteral(ExpressionType.LONG, 3), Expressions.calciteLiteralToDruidLiteral(plannerContext, rexBuilder.makeIntervalLiteral(BigDecimal.valueOf(3), new SqlIntervalQualifier(TimeUnit.YEAR, TimeUnit.MONTH, SqlParserPos.ZERO))));
    assertDruidLiteral(new DruidLiteral(ExpressionType.STRING, "123"), Expressions.calciteLiteralToDruidLiteral(plannerContext, rexBuilder.makeCast(rexBuilder.getTypeFactory().createSqlType(SqlTypeName.VARCHAR), rexBuilder.makeExactLiteral(BigDecimal.valueOf(123.7), rexBuilder.getTypeFactory().createSqlType(SqlTypeName.INTEGER)))));
    assertDruidLiteral(new DruidLiteral(ExpressionType.DOUBLE, 123.0), Expressions.calciteLiteralToDruidLiteral(plannerContext, rexBuilder.makeCast(rexBuilder.getTypeFactory().createSqlType(SqlTypeName.DOUBLE), rexBuilder.makeExactLiteral(BigDecimal.valueOf(123L), rexBuilder.getTypeFactory().createSqlType(SqlTypeName.INTEGER)))));
    Assert.assertNull(Expressions.calciteLiteralToDruidLiteral(plannerContext, rexBuilder.makeCast(rexBuilder.getTypeFactory().createSqlType(SqlTypeName.DATE), Calcites.jodaToCalciteTimestampLiteral(rexBuilder, DateTimes.of("2000-01-02T03:04:05"), DateTimeZone.UTC, DruidTypeSystem.DEFAULT_TIMESTAMP_PRECISION))));
}

