@Test
public void testTombstoneSegmentIsNotRefreshed() throws IOException {
    String brokerInternalQueryConfigJson = "{\"context\": { \"priority\": 5} }";
    TestHelper.makeJsonMapper();
    InternalQueryConfig internalQueryConfig = MAPPER.readValue(MAPPER.writeValueAsString(MAPPER.readValue(brokerInternalQueryConfigJson, InternalQueryConfig.class)), InternalQueryConfig.class);
    QueryLifecycleFactory factoryMock = EasyMock.createMock(QueryLifecycleFactory.class);
    QueryLifecycle lifecycleMock = EasyMock.createMock(QueryLifecycle.class);
    BrokerSegmentMetadataCache schema = new BrokerSegmentMetadataCache(factoryMock, serverView, SEGMENT_CACHE_CONFIG_DEFAULT, new NoopEscalator(), internalQueryConfig, new NoopServiceEmitter(), new PhysicalDatasourceMetadataFactory(globalTableJoinable, segmentManager), new NoopCoordinatorClient(), CentralizedDatasourceSchemaConfig.create());
    Map<String, Object> queryContext = ImmutableMap.of(QueryContexts.PRIORITY_KEY, 5, QueryContexts.BROKER_PARALLEL_MERGE_KEY, false);
    DataSegment segment = newSegment("test", 0);
    DataSegment tombstone = DataSegment.builder().dataSource("test").interval(Intervals.of("2012-01-01/2012-01-02")).version(DateTimes.of("2012-01-01T11:22:33.444Z").toString()).shardSpec(new TombstoneShardSpec()).loadSpec(Collections.singletonMap("type", DataSegment.TOMBSTONE_LOADSPEC_TYPE)).size(0).build();
    final ImmutableDruidServer historicalServer = druidServers.stream().filter(s -> s.getType().equals(ServerType.HISTORICAL)).findAny().orElse(null);
    Assert.assertNotNull(historicalServer);
    final DruidServerMetadata historicalServerMetadata = historicalServer.getMetadata();
    schema.addSegment(historicalServerMetadata, segment);
    schema.addSegment(historicalServerMetadata, tombstone);
    Assert.assertFalse(schema.getSegmentsNeedingRefresh().contains(tombstone.getId()));
    List<SegmentId> segmentIterable = ImmutableList.of(segment.getId(), tombstone.getId());
    SegmentMetadataQuery expectedMetadataQuery = new SegmentMetadataQuery(new TableDataSource(segment.getDataSource()), new MultipleSpecificSegmentSpec(segmentIterable.stream().filter(id -> !id.equals(tombstone.getId())).map(SegmentId::toDescriptor).collect(Collectors.toList())), new AllColumnIncluderator(), false, queryContext, EnumSet.noneOf(SegmentMetadataQuery.AnalysisType.class), false, null, null);
    EasyMock.expect(factoryMock.factorize()).andReturn(lifecycleMock).once();
    EasyMock.expect(lifecycleMock.runSimple(expectedMetadataQuery, AllowAllAuthenticator.ALLOW_ALL_RESULT, AuthorizationResult.allowWithRestriction(ImmutableMap.of("test", Optional.of(NoRestrictionPolicy.instance()))))).andReturn(QueryResponse.withEmptyContext(Sequences.empty()));
    EasyMock.replay(factoryMock, lifecycleMock);
    Set<SegmentId> segmentsToRefresh = new HashSet<>();
    segmentsToRefresh.add(segment.getId());
    schema.refresh(segmentsToRefresh, Collections.singleton("test"));
    // verify that metadata is not issued for tombstone segment
    EasyMock.verify(factoryMock, lifecycleMock);
    // Verify that datasource schema building logic doesn't mark the tombstone segment for refresh
    Assert.assertFalse(schema.getSegmentsNeedingRefresh().contains(tombstone.getId()));
    AvailableSegmentMetadata availableSegmentMetadata = schema.getAvailableSegmentMetadata("test", tombstone.getId());
    Assert.assertNotNull(availableSegmentMetadata);
    // fetching metadata for tombstone segment shouldn't mark it for refresh
    Assert.assertFalse(schema.getSegmentsNeedingRefresh().contains(tombstone.getId()));
    Set<AvailableSegmentMetadata> metadatas = new HashSet<>();
    schema.iterateSegmentMetadata().forEachRemaining(metadatas::add);
    Assert.assertEquals(1, metadatas.stream().filter(metadata -> metadata.getSegment().isTombstone()).count());
    // iterating over entire metadata doesn't cause tombstone to be marked for refresh
    Assert.assertFalse(schema.getSegmentsNeedingRefresh().contains(tombstone.getId()));
}

